import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
const pasta=resolve('output/picos-abertura-20261117');
const ler=async p=>JSON.parse(await readFile(resolve(pasta,p),'utf8'));
const anterior=await ler('antes-26-final/resultados.json'),inicio=await ler('antes-inicio-26/resultados.json'),novo=await ler('depois-26-final/resultados.json');
const antes=[...anterior.resultados.filter(r=>r.rota!=='/'),...inicio.resultados],depois=novo.resultados;
assert.equal(antes.length,156);assert.equal(depois.length,156);assert.equal(anterior.falhas.length+inicio.falhas.length+novo.falhas.length,0);
const chave=r=>`${r.perfil}|${r.mobile}|${r.rota}`;assert.equal(new Set(antes.map(chave)).size,156);assert.deepEqual(new Set(antes.map(chave)),new Set(depois.map(chave)));
const fmt=n=>n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const stats=rows=>{const a=rows.map(r=>r.segundos).sort((x,y)=>x-y);return{n:a.length,mediana:(a[Math.floor((a.length-1)/2)]+a[Math.ceil((a.length-1)/2)])/2,p95:a[Math.ceil(a.length*.95)-1],max:a.at(-1),acima5:a.filter(x=>x>5).length}};
const resumo={geradoEm:new Date().toISOString(),buildAntes:anterior.build,buildDepois:novo.build,desktop:{antes:stats(antes.filter(r=>!r.mobile)),depois:stats(depois.filter(r=>!r.mobile))},celular:{antes:stats(antes.filter(r=>r.mobile)),depois:stats(depois.filter(r=>r.mobile))}};
const diagnostico=await ler('diagnostico-antes/resultados.json');const lento=diagnostico.resultados.find(r=>r.perfil==='assistencia_celulares'&&!r.mobile);const dns=lento.rede.filter(r=>r.timing?.dnsEnd>0).map(r=>(r.timing.dnsEnd-r.timing.dnsStart)/1000).sort((a,b)=>b-a)[0];
const seguranca=await ler('seguranca-proxy.json'),provaAntes=await ler('prova-dns-antes/resultados.json'),provaDepois=await ler('prova-dns-depois/resultados.json'),servidor=await ler('servidor-supabase.json');
assert(seguranca.checks.every(r=>r.ok));assert.equal(provaAntes.falhas.length,2);assert.equal(provaDepois.falhas.length,0);
const extras=[];for(const fase of ['depois-repeticao-26','depois-rede-limitada','depois-pwa']){try{const r=await ler(fase+'/resultados.json');assert.equal(r.resultados.length,fase==='depois-repeticao-26'?52:8);extras.push({fase,...r});assert.equal(r.falhas.length,0)}catch(e){if(e.code!=='ENOENT')throw e}}
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const nomes={'/':'Tela inicial','/clientes':'Clientes','/estoque':'Estoque'};
const rows=antes.map(a=>{const d=depois.find(x=>chave(x)===chave(a));return{perfil:a.perfil,dispositivo:a.mobile?'Celular emulado':'Desktop',tela:nomes[a.rota],antes_s:a.segundos,depois_s:d.segundos,diferenca_s:d.segundos-a.segundos}});
await writeFile(resolve(pasta,'tempos-antes-depois.csv'),'\ufeff'+['Subsistema;Dispositivo;Tela;Antes (s);Depois (s);Diferença (s)',...rows.map(r=>[r.perfil,r.dispositivo,r.tela,...[r.antes_s,r.depois_s,r.diferenca_s].map(n=>n.toFixed(3).replace('.',','))].join(';'))].join('\r\n'));
await writeFile(resolve(pasta,'resumo.json'),JSON.stringify({...resumo,extras:extras.map(e=>({fase:e.fase,n:e.resultados.length,estatisticas:stats(e.resultados),falhas:e.falhas.length})),comparacao:rows},null,2));
const metricas=Object.entries({Desktop:resumo.desktop,'Celular emulado':resumo.celular}).map(([nome,r])=>`<tr><th>${nome}</th><td>${fmt(r.antes.mediana)} → <b>${fmt(r.depois.mediana)}</b></td><td>${fmt(r.antes.p95)} → <b>${fmt(r.depois.p95)}</b></td><td>${fmt(r.antes.max)} → <b>${fmt(r.depois.max)}</b></td><td>${r.antes.acima5} → <b>${r.depois.acima5}</b></td></tr>`).join('');
const porTela=Object.entries(nomes).flatMap(([rota,nome])=>[false,true].map(mobile=>{const a=stats(antes.filter(r=>r.rota===rota&&r.mobile===mobile)),d=stats(depois.filter(r=>r.rota===rota&&r.mobile===mobile));return`<tr><th>${nome} · ${mobile?'celular':'desktop'}</th><td>${fmt(a.mediana)} → <b>${fmt(d.mediana)}</b></td><td>${fmt(a.p95)} → <b>${fmt(d.p95)}</b></td><td>${fmt(a.max)} → <b>${fmt(d.max)}</b></td></tr>`})).join('');
const perfis=[...new Set(antes.map(r=>r.perfil))];const tabelaPerfis=perfis.map(p=>`<tr><th>${esc(p.replaceAll('_',' '))}</th>${[false,true].map(m=>{const a=antes.find(r=>r.perfil===p&&r.mobile===m&&r.rota==='/'),d=depois.find(r=>r.perfil===p&&r.mobile===m&&r.rota==='/');return`<td>${fmt(a.segundos)}</td><td><a href="depois-26-final/${p}-${m?'celular':'desktop'}-1-inicio.png"><b>${fmt(d.segundos)}</b></a></td>`}).join('')}</tr>`).join('');
const extraHtml=extras.map(e=>{const s=stats(e.resultados);return`<li><b>${esc(e.fase)}</b>: ${s.n} aberturas, ${e.falhas.length} falhas. Mediana ${fmt(s.mediana)} s, P95 ${fmt(s.p95)} s, máximo ${fmt(s.max)} s. <a href="${e.fase}/resultados.json">Dados brutos</a>.</li>`}).join('');
const html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Abertura inicial · diagnóstico e tempos</title><style>
:root{font-family:system-ui,sans-serif;color:#18302b;background:#edf2ef}*{box-sizing:border-box}body{margin:0}main{max-width:1080px;margin:32px auto;background:white;padding:44px;border-radius:18px}h1{font-size:36px;line-height:1.15;margin:12px 0}h2{font-size:23px;margin:38px 0 15px}p,li{line-height:1.65}small,.muted{color:#54675e}.pill{display:inline-block;background:#e5efdc;border-radius:30px;padding:7px 13px;font-weight:700}.notice{padding:18px 22px;background:#fff4d8;border-left:5px solid #b07918;border-radius:8px;margin:24px 0}.good{background:#eef7ec;border-left-color:#4a8056}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px;margin:14px 0}th,td{padding:12px;border-bottom:1px solid #cad8cd;text-align:left}thead th{background:#173b30;color:white}tbody tr:nth-child(even){background:#f0f5f1}td{font-variant-numeric:tabular-nums;white-space:nowrap}a{color:#1f6149}code{overflow-wrap:anywhere}.trace{display:flex;height:36px;border-radius:6px;overflow:hidden;margin:10px 0}.trace span{display:grid;place-items:center;font-size:12px;background:#cedebc}.trace .dns{background:#aa4c32;color:white;width:${dns/lento.segundos*100}%}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.box{padding:18px;background:#f3f6f3;border:1px solid #dce5de;border-radius:10px}.box strong{font-size:24px;display:block}footer{border-top:1px solid #ddd;padding-top:18px;margin-top:40px;font-size:13px}@media(max-width:650px){main{padding:20px;margin:0;border-radius:0}h1{font-size:28px}.grid{grid-template-columns:1fr}th,td{padding:9px;font-size:12px}}@media print{body{background:white}main{margin:0;padding:8mm;max-width:none}h2{break-after:avoid}tr,.box,.notice{break-inside:avoid}thead{display:table-header-group}.scroll{overflow:visible}a{color:inherit}} </style><main>
<span class="pill">17/11/2026 · 26 subsistemas</span><h1>Abertura inicial: causa identificada e correção medida</h1><p>Comparação em segundos até os dados ficarem visíveis, com sessões reais das empresas fictícias de teste. Inclui tela inicial, clientes e estoque.</p>
<div class="notice"><b>Correção local; publicação pendente.</b> O build corrigido foi executado em servidor local com o Supabase real. O endereço publicado ainda precisa receber o frontend e as rotas de proxy juntos. Os resultados abaixo não representam uma medição da correção já publicada na Vercel. Não houve alteração na conta de hospedagem nem publicação nesta rodada.</div>
<div class="grid"><div class="box"><strong>312 aberturas comparáveis</strong>156 antes + 156 depois · 26 perfis × 2 tamanhos × 3 telas.</div><div class="box"><strong>${seguranca.checks.length} verificações de acesso</strong>Dados, isolamento das empresas, autenticação e cache: todas passaram.</div></div>
<h2>1. Causa comprovada</h2><p>Em uma abertura de <b>${fmt(lento.segundos)} s</b>, o Chrome gastou <b>${fmt(dns)} s resolvendo o endereço do Supabase</b>, na requisição CORS anterior à consulta de acesso. O HTML já estava disponível e o atraso ocorreu antes de o pedido chegar ao banco. Esse tempo é capturado pelo protocolo de rede do Chrome, incluindo a requisição de preflight, ausente dos registros simplificados anteriores.</p>
<div class="trace"><span class="dns">DNS: ${fmt(dns)} s</span><span style="flex:1">Outras etapas</span></div><p>No gateway do Supabase, ${servidor.quantidade} consultas de acesso na janela analisada tiveram mediana de <b>${servidor.mediana_ms} ms</b>, P95 de <b>${fmt(servidor.p95_ms)} ms</b> e máximo de <b>${servidor.max_ms} ms</b>. Esse tempo de origem não inclui DNS, transporte nem renderização. <a href="servidor-supabase.json">Registro da consulta</a> · <a href="diagnostico-antes/resultados.json">Traços do Chrome</a>.</p>
<h2>2. O que mudou</h2><p>As chamadas REST e de autenticação agora usam o endereço do próprio aplicativo. O servidor as encaminha ao projeto Supabase configurado. Isso retira a resolução adicional do domínio e o preflight CORS do caminho de abertura do navegador. A identidade da sessão, o projeto, os tokens, as funções, as verificações de MFA e as permissões do banco continuam os mesmos.</p><ul><li>Encaminhamento restrito a REST e Auth, com destino fixo; outros serviços continuam no caminho original.</li><li>Sem cache das respostas privadas, sem cookies do site no encaminhamento e sem novas tentativas automáticas de gravação.</li><li>Vite e preview preparados; regras correspondentes incluídas no arquivo de hospedagem. Outros projetos sem rotas compatíveis mantêm o acesso direto.</li><li>Nenhuma migração, pagamento, alteração de estoque ou gravação de dados de negócio foi necessária.</li></ul>
<h2>3. Tempos antes e depois</h2><p>Todos os valores estão em segundos. P95 é o valor que abrange 95% das amostras, pelo método do posto mais próximo. Os máximos e os picos também estão expostos.</p><div class="scroll"><table><thead><tr><th>Dispositivo · 78 amostras por versão</th><th>Mediana</th><th>P95</th><th>Máximo</th><th>Acima de 5 s</th></tr></thead><tbody>${metricas}</tbody></table></div>
<div class="scroll"><table><thead><tr><th>Tela · 26 amostras por versão</th><th>Mediana antes → depois</th><th>P95 antes → depois</th><th>Máximo antes → depois</th></tr></thead><tbody>${porTela}</tbody></table></div>
<h2>4. Tela inicial de cada subsistema</h2><p>Uma abertura fria por perfil e dispositivo, em cada versão. A planilha inclui também clientes e estoque e conserva diferenças positivas quando uma amostra ficou mais lenta.</p><div class="scroll"><table><thead><tr><th>Subsistema</th><th>Desktop antes</th><th>Desktop depois</th><th>Celular antes</th><th>Celular depois</th></tr></thead><tbody>${tabelaPerfis}</tbody></table></div>
<h2>5. Prova controlada e verificações adicionais</h2><p>O DNS do Supabase foi bloqueado <b>apenas no Chrome de teste</b>. A versão anterior não abriu em nenhum dos dois dispositivos; a nova abriu em ${fmt(provaDepois.resultados.find(r=>!r.mobile).segundos)} s no desktop e ${fmt(provaDepois.resultados.find(r=>r.mobile).segundos)} s no celular. As consultas continuaram indo ao Supabase real pelo servidor. Nenhum IP foi fixado no produto e nenhuma configuração de DNS do computador foi alterada.</p><ul><li><a href="prova-dns-antes/resultados.json">Controle negativo: duas falhas esperadas</a> · <a href="prova-dns-depois/resultados.json">Correção com DNS direto indisponível</a>.</li><li><a href="seguranca-proxy.json">137 verificações reais</a>: mesmos dados e acesso nos 26 perfis, outra empresa recusada, mesmo nível de autenticação, token inválido recusado, login, renovação, saída e ausência de cache.</li><li><a href="testes-transporte-acesso.log">9 testes de transporte e repetição de acesso</a>; <a href="testes-pwa.log">4 testes do PWA</a>, incluindo nenhuma interceptação das APIs privadas; <a href="testes-recuperacao.log">recuperação de acesso</a>. TypeScript e lint concluídos sem erros.</li>${extraHtml}</ul>
<h2>6. Método e limites</h2><ul><li>Chrome instalado, desktop 1920×1080; celular <b>emulado</b> em 390×844, toque e CPU reduzida em 4 vezes. Não houve teste em aparelho físico nesta rodada.</li><li>Contexto novo a cada abertura, sem cache HTTP anterior. Autenticação válida carregada antes da navegação; o tempo de digitar senha não faz parte da abertura. Na matriz principal, service worker bloqueado para separar rede e renderização; PWA e rede limitada estão identificados à parte quando presentes.</li><li>Relógio do navegador começa na navegação e termina com listas/indicadores preenchidos. Não se usa apenas a chegada do HTML ou o evento de carregamento.</li><li>A medição inicial dos painéis foi refinada para capturar mudanças de texto do React. As 52 amostras de início usadas aqui vêm de <code>antes-inicio-26</code>; as 104 de clientes/estoque, de <code>antes-26-final</code>. A rodada exploratória <code>antes-26</code>, interrompida por seletor incompatível com assistência, foi preservada e não integra o comparativo.</li><li>Uma expectativa inicial de 401 para token inválido foi corrigida: o serviço retorna 403. O teste final compara resposta e status direto versus proxy. A primeira execução foi preservada em <code>seguranca-proxy-primeira-execucao.json</code>.</li><li>A correção remove a dependência de DNS adicional observada neste ambiente. Não garante tempos idênticos em toda rede, aparelho ou hospedagem. A medição depois da publicação continua pendente; o proxy em produção acrescenta um salto pela hospedagem.</li></ul>
<h2>7. Evidências e reprodução</h2><p><a href="tempos-antes-depois.csv">Planilha com os 156 pares de medições</a> · <a href="resumo.json">Resumo em JSON</a> · <a href="antes-26-final/resultados.json">Antes: listas e traços</a> · <a href="antes-inicio-26/resultados.json">Antes: painéis</a> · <a href="depois-26-final/resultados.json">Depois: todas as telas</a>.</p><p>Scripts no projeto: <code>scripts/investigar-abertura-20261117.mjs</code>, <code>scripts/conferir-proxy-abertura-20261117.mjs</code>, <code>scripts/testar-transporte-supabase.mjs</code> e <code>scripts/relatorio-picos-abertura-20261117.mjs</code>. O medidor aceita QA_BUILD, QA_ROTAS, QA_FASE, QA_PERFIS, QA_DNS_BLOQUEADO, QA_SW e QA_REDE_LENTA.</p>
<p>Referências técnicas consultadas: <a href="https://supabase.com/docs/reference/javascript/initializing">Supabase: custom fetch</a>, <a href="https://vite.dev/config/server-options#server-proxy">Vite: proxy</a>, <a href="https://vercel.com/docs/routing/rewrites">Vercel: encaminhamento externo</a> e <a href="https://vercel.com/docs/caching/cdn-cache">controle de cache</a>.</p><footer>Build anterior: ${esc(anterior.build.build)} · Build corrigido: ${esc(novo.build.build)}. Relatório gerado em ${new Date().toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}. Somente empresas fictícias; nenhum login, senha ou token consta deste relatório.</footer></main></html>`;
await writeFile(resolve(pasta,'relatorio.html'),html.replace('<h2>6. Método e limites</h2>','<p>Rede limitada: 1,6 Mbps de download, 0,75 Mbps de upload e 150 ms de latência artificial. São oito aberturas adicionais, em quatro famílias de subsistemas, servidas pelo preview local, sem a CDN de produção. O teste com PWA mantém cada página aberta por mais 11 segundos após a apresentação dos dados. As capturas de tela de cada painel estão nos links dos tempos da tabela acima.</p><h2>6. Método e limites</h2>'));console.log(JSON.stringify(resumo,null,2));
